<?php
declare(strict_types=1);

namespace Madovai;

/**
 * SQLite access.
 *  - `gtfs()`  : read-only static data, generated by bin/build-data.php (data/madovai.sqlite)
 *  - `state()` : read-write user state (push subscriptions + reminders)  (data/state.sqlite)
 */
final class Db
{
    private static ?\PDO $gtfs = null;
    private static ?\PDO $state = null;

    public static function gtfsPath(): string
    {
        return Config::dataDir() . '/madovai.sqlite';
    }

    public static function gtfs(): \PDO
    {
        if (self::$gtfs === null) {
            $path = self::gtfsPath();
            if (!is_file($path)) {
                throw new NotReady('Dati non ancora generati: esegui "php bin/build-data.php" sul server.');
            }
            // PDO::SQLITE_* constants are deprecated since PHP 8.5 (Pdo\Sqlite::* since 8.4).
            $modern = PHP_VERSION_ID >= 80400;
            $pdo = new \PDO('sqlite:' . $path, null, null, [
                \PDO::ATTR_ERRMODE => \PDO::ERRMODE_EXCEPTION,
                \PDO::ATTR_DEFAULT_FETCH_MODE => \PDO::FETCH_ASSOC,
                ($modern ? \Pdo\Sqlite::ATTR_OPEN_FLAGS : \PDO::SQLITE_ATTR_OPEN_FLAGS)
                    => ($modern ? \Pdo\Sqlite::OPEN_READONLY : \PDO::SQLITE_OPEN_READONLY),
            ]);
            $pdo->exec('PRAGMA query_only = ON');
            $pdo->exec('PRAGMA cache_size = -20000');
            self::$gtfs = $pdo;
        }
        return self::$gtfs;
    }

    public static function state(): \PDO
    {
        if (self::$state === null) {
            $pdo = new \PDO('sqlite:' . Config::dataDir() . '/state.sqlite', null, null, [
                \PDO::ATTR_ERRMODE => \PDO::ERRMODE_EXCEPTION,
                \PDO::ATTR_DEFAULT_FETCH_MODE => \PDO::FETCH_ASSOC,
            ]);
            $pdo->exec('PRAGMA journal_mode = WAL');
            $pdo->exec('PRAGMA busy_timeout = 5000');
            self::$state = $pdo;
        }
        return self::$state;
    }
}
